arguments.command:
curl -s -X POST https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{"query":"{ __schema { mutationType { fields(includeDeprecated: true) { name description args { name type { kind name ofType { kind name } } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
for f in d['data']['__schema']['mutationType']['fields']:
    if f['name'].lower().startswith('team'):
        print(f['name'], '-', f['description'])
        for a in f['args']:
            t=a['type']; inner=t.get('ofType') or {}
            print('   ', a['name'], ':', t['kind'], inner.get('name',''))
"

