import json
d=json.load(open('/tmp/linear_schema.json'))
types=d['data']['__schema']['types']
# find mutation type and search all fields
for t in types:
    if t['name']=='Mutation':
        names=[f['name'] for f in t['fields']]
        print('teamUpdate' in names, len(names))
        print([n for n in names if 'eam' in n])
# TeamUpdateInput fields
for t in types:
    if t['name']=='TeamUpdateInput':
        print('TeamUpdateInput fields:')
        for f in t['inputFields']:
            tt=f['type']
            inner=tt.get('ofType') or {}
            print('  ',f['name'], tt['kind'], inner.get('name',''))
"

